/**
 * @ignore
 * @method
 * @name opinion#parseOpinionMarket
 * @description converts a single raw opinion market into one ccxt market with yes/no outcomes
 * @param {object} raw the raw opinion market object
 * @param {string} [eventSlug] the slug of the parent event
 * @returns {object} a [market structure](https://docs.ccxt.com/#/?id=market-structure)
 */
func (this *Opinion) ParseOpinionMarket(raw any, optionalArgs ...any) any {
	// {
	//     "chainId": "56",
	//     "conditionId": "469db44df1309dac7cf9fcaa142562f3c89719d47277e095d021c1561166539a",
	//     "createdAt": 1778750719,
	//     "cutoffAt": 0,
	//     "isResolvableByAI": true,
	//     "marketId": 16565,
	//     "marketTitle": "10–15s",
	//     "noLabel": "No",
	//     "noTokenId": "48641131337815600205538397357674754469573755318952418769815647071528778171134",
	//     "questionId": "63907f471c045499f69b5ea157bdea1942f9d53b6e5e767ae69f4d148aeeefae",
	//     "quoteToken": "0x55d398326f99059fF775485246999027B3197955",
	//     "rebate": {
	//         "maker": 0.5
	//     },
	//     "resolvedAt": 1779342061,
	//     "resultTokenId": "107063188116504514729209026208703521982564071792212276771696073817845504321279",
	//     "rules": "",
	//     "slug": "how-long-will-trump-and-xi-shake-hands-when-they-meet-10-15s",
	//     "status": 4,
	//     "statusEnum": "Resolved",
	//     "volume": "50",
	//     "yesLabel": "Yes",
	//     "yesTokenId": "107063188116504514729209026208703521982564071792212276771696073817845504321279"
	// }
	eventSlug := ccxt.GetArg(optionalArgs, 0, nil)
	_ = eventSlug
	var marketId *string = this.SafeString(raw, "marketId")
	var slug *string = this.SafeString(raw, "slug")
	var effectiveEventSlug any = eventSlug
	if (eventSlug != nil) && (slug != nil) && (ccxt.GetIndexOf(slug, eventSlug) == 0) {
		effectiveEventSlug = nil
	}
	var marketSymbol any = this.SlugToMarketSymbol(effectiveEventSlug, slug)
	var statusEnum *string = this.SafeString(raw, "statusEnum")
	var active bool = (statusEnum != nil && *statusEnum == "Activated")
	var resolved bool = (statusEnum != nil && *statusEnum == "Resolved")
	var resultTokenId *string = this.SafeString(raw, "resultTokenId")
	var hasResult bool = resolved && (resultTokenId != nil) && (resultTokenId == nil || *resultTokenId != "")
	var outcomeLabels []any = []any{this.SafeString(raw, "yesLabel", "YES"), this.SafeString(raw, "noLabel", "NO")}
	var outcomeTokenIds []any = []any{this.SafeString(raw, "yesTokenId"), this.SafeString(raw, "noTokenId")}
	var outcomes []any = []any{}
	var resolvedOutcome any = nil
	for i := 0; i < len(outcomeLabels); i++ {
		var label *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(outcomeLabels) {
				return ccxt.DerefScalar(outcomeLabels[i])
			}
			return nil
		}())
		var tokenId *string = ccxt.SafeStringPtr(func() any {
			if i >= 0 && i < len(outcomeTokenIds) {
				return ccxt.DerefScalar(outcomeTokenIds[i])
			}
			return nil
		}())
		var outcomeHandle any = this.SlugToOutcomeSymbol(effectiveEventSlug, slug, label)
		var winner any = nil
		var settleFraction any = nil
		if hasResult {
			winner = (tokenId == resultTokenId || (tokenId != nil && resultTokenId != nil && *tokenId == *resultTokenId))
			settleFraction = func() int {
				if winner == true {
					return 1
				}
				return 0
			}()
			if winner == true {
				resolvedOutcome = outcomeHandle
			}
		}
		outcomes = append(outcomes, map[string]any{
			"id":             tokenId,
			"outcomeId":      tokenId,
			"outcome":        outcomeHandle,
			"market":         marketSymbol,
			"label":          label,
			"active":         active,
			"winner":         winner,
			"settleFraction": settleFraction,
			"info":           raw,
		})
	}
	var marketResolvedOutcome any = resolvedOutcome
	// the venue sends cutoffAt 0 for markets without a scheduled cutoff - map it to
	// undefined instead of the epoch, same for the event-level end date
	var expiryTimestamp *int64 = nil
	if !ccxt.IsEqual(this.SafeInteger(raw, "cutoffAt", 0), 0) {
		expiryTimestamp = this.SafeTimestamp(raw, "cutoffAt")
	}
	var created *int64 = this.SafeTimestamp(raw, "createdAt")
	return map[string]any{
		"id":              marketId,
		"market":          marketSymbol,
		"base":            "USDT",
		"quote":           "USDT",
		"settle":          nil,
		"baseId":          marketId,
		"quoteId":         "USDT",
		"settleId":        nil,
		"type":            "prediction",
		"marketType":      "binary",
		"executionModel":  "clob",
		"spot":            false,
		"margin":          false,
		"swap":            false,
		"future":          false,
		"option":          false,
		"prediction":      true,
		"active":          active,
		"resolved":        resolved,
		"resolvedOutcome": marketResolvedOutcome,
		"contract":        false,
		"linear":          nil,
		"inverse":         nil,
		"contractSize":    nil,
		"expiry":          expiryTimestamp,
		"expiryDatetime":  this.Iso8601(expiryTimestamp),
		"strike":          nil,
		"optionType":      nil,
		"taker":           ccxt.GetValue(this.Fees["trading"], "taker"),
		"maker":           ccxt.GetValue(this.Fees["trading"], "maker"),
		"percentage":      true,
		"tierBased":       false,
		"feeSide":         "get",
		"precision": map[string]any{
			"amount": nil,
			"price":  nil,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": 1,
				"max": 1,
			},
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"price": map[string]any{
				"min": 0,
				"max": 1,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"outcomes": outcomes,
		"info":     raw,
		"created":  created,
	}
}

/**
 * @method
 * @name opinion#fetchEvents
 * @description fetches Opinion's categorical markets - scope required via query/queries/tags/eventId/slug/labelId
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/market
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.labelId] filter by opinion category label id
 * @param {int} [params.limit] max number of events to fetch (paginated server-side; defaults to options.maxFetchEventsResults, 100)
 * @returns {object[]} an array of event structures
 */
func (this *Opinion) FetchEventsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchEventsBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) fetchEventsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	this.RequireEventQuery(params)
	var queries []any = this.ParseSearchQueries(params)
	var eventId *string = this.SafeString(params, "eventId")
	var slug *string = this.SafeString(params, "slug")
	if (eventId != nil) || (slug != nil) {
		var singleRest map[string]any = ccxt.MapTyped(this.Omit(params, []any{"eventId", "slug", "query", "queries", "tags", "status", "sort", "searchIn", "limit"}))
		var singleResponse map[string]any = nil
		if slug != nil {

			singleResponse = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPublicGetMarketSlugSlug(this.Extend(map[string]any{
				"slug": slug,
			}, singleRest))).Raw))
		} else {

			singleResponse = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPublicGetMarketCategoricalMarketId(this.Extend(map[string]any{
				"marketId": eventId,
			}, singleRest))).Raw))
		}
		var singleResult map[string]any = ccxt.SafeMapTyped(singleResponse, "result")
		var singleData any = this.SafeDict(singleResult, "data", map[string]any{})
		var single any = this.ParseEvent(singleData)
		this.IndexEventOutcomes(single)

		ch <- this.ApplyEventFetchParams([]any{single}, params, queries)
		return nil
	}
	var rest map[string]any = ccxt.MapTyped(this.Omit(params, []any{"query", "queries", "tags", "status", "sort", "searchIn", "limit"}))
	var pageLimit *int64 = this.SafeInteger(this.Options, "defaultFetchEventsLimit", 20)
	var userLimit *int64 = this.SafeInteger(params, "limit")
	// bound how many events are actually FETCHED: the user limit when given, otherwise
	// options.maxFetchEventsResults - the scope filters keep the listing narrow, but a broad
	// label can still hold more than one page
	var fetchCap *int64 = this.SafeInteger(this.Options, "maxFetchEventsResults", 100)
	if userLimit != nil {
		fetchCap = userLimit
	}
	var maxPages *int64 = this.SafeInteger(this.Options, "maxEventsPages", 50)
	var rawEvents []any = []any{}
	var page any = 1
	var fetchedRawCount any = 0
	for true {
		var reqLimit any = pageLimit
		var remaining any = ccxt.Subtract(fetchCap, fetchedRawCount)
		if ccxt.IsLessThan(remaining, reqLimit) {
			reqLimit = remaining
		}
		if ccxt.IsLessThanOrEqual(reqLimit, 0) {
			break
		}
		var request map[string]any = map[string]any{
			"marketType": 1,
			"limit":      reqLimit,
			"page":       page,
		}

		var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPublicGetMarket(this.Extend(request, rest))).Raw))
		var result map[string]any = ccxt.SafeMapTyped(response, "result")
		var pageEvents []any = ccxt.SafeListTyped(result, "list")
		var pageEventsLength int = len(pageEvents)
		fetchedRawCount = this.Sum(fetchedRawCount, pageEventsLength)
		for i := 0; i < pageEventsLength; i++ {
			rawEvents = append(rawEvents, func() any {
				if i >= 0 && i < len(pageEvents) {
					return ccxt.DerefScalar(pageEvents[i])
				}
				return nil
			}())
		}
		var total *int64 = this.SafeInteger(result, "total")
		if (ccxt.IsLessThan(pageEventsLength, reqLimit)) || (ccxt.IsGreaterThanOrEqual(page, maxPages)) || ((total != nil) && (ccxt.IsGreaterThanOrEqual(fetchedRawCount, total))) || (ccxt.IsGreaterThanOrEqual(fetchedRawCount, fetchCap)) {
			break
		}
		page = this.Sum(page, 1)
	}
	var rawEventsLength int = len(rawEvents)
	var parsedEvents []any = []any{}
	if this.Markets == nil {
		this.Markets = this.CreateSafeDictionary()
	}
	for i := 0; i < rawEventsLength; i++ {
		var event any = this.ParseEvent(func() any {
			if i >= 0 && i < len(rawEvents) {
				return ccxt.DerefScalar(rawEvents[i])
			}
			return nil
		}())
		parsedEvents = append(parsedEvents, event)
		// register the parsed markets so populateOutcomes can index their outcomes
		var eventMarkets []any = ccxt.SafeListTyped(event, "markets")
		var eventMarketsLength int = len(eventMarkets)
		for mi := 0; mi < eventMarketsLength; mi++ {
			var m any = func() any {
				if mi >= 0 && mi < len(eventMarkets) {
					return ccxt.DerefScalar(eventMarkets[mi])
				}
				return nil
			}()
			ccxt.AddElementToObject(this.Markets, ccxt.GetValue(m, "market"), m)
		}
	}
	this.PopulateOutcomes()

	ch <- this.ApplyEventFetchParams(parsedEvents, params, queries)
	return nil
}

