/**
 * @method
 * @name opinion#parsePredictionOrder
 * @description parses a raw opinion order object into a unified prediction order structure
 * @param {object} order the raw opinion OrderData object
 * @param {object} [market] the outcome object the order belongs to
 * @returns {object} a [prediction order structure](https://docs.ccxt.com/#/?id=prediction-order-structure)
 */
func (this *Opinion) ParsePredictionOrder(order any, optionalArgs ...any) any {
	//
	//     {
	//         "orderId": "...",
	//         "marketId": 1094,
	//         "side": 0,
	//         "sideEnum": "Buy",
	//         "tradingMethod": 2,
	//         "tradingMethodEnum": "Limit",
	//         "price": "0.01",
	//         "orderShares": "5",
	//         "orderAmount": "0.05",
	//         "filledShares": "0",
	//         "filledAmount": "0",
	//         "profit": "0",
	//         "status": 1,
	//         "statusEnum": "Pending",
	//         "createdAt": 1785500000,
	//         "expiresAt": 0,
	//         "postOnly": false
	//     }
	//
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var id *string = this.SafeString(order, "orderId")
	var marketAny any = market
	var statusEnum *string = this.SafeString(order, "statusEnum")
	var status *string = this.ParseOrderStatus(statusEnum)
	var sideEnum *string = this.SafeStringLower(order, "sideEnum")
	var tradingMethodEnum *string = this.SafeStringLower(order, "tradingMethodEnum")
	var timestamp *int64 = this.SafeTimestamp(order, "createdAt")
	return this.SafePredictionOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      nil,
		"info":               order,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"outcome":            this.SafeString(marketAny, "outcome"),
		"outcomeId":          this.SafeString2(marketAny, "outcomeId", "id"),
		"label":              this.SafeString(marketAny, "label"),
		"market":             this.SafeString2(marketAny, "market", "outcome"),
		"type":               tradingMethodEnum,
		"side":               sideEnum,
		"price":              this.SafeNumber(order, "price"),
		"amount":             this.SafeNumber(order, "orderShares"),
		"cost":               this.SafeNumber(order, "filledAmount"),
		"filled":             this.SafeNumber(order, "filledShares"),
		"fee":                nil,
		"trades":             []any{},
	}, market)
}

