/**
 * @method
 * @name opinion#fetchMyTrades
 * @description fetches the authenticated user's trades
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/trade
 * @param {string} [outcome] filter by unified outcome or outcome token id
 * @param {int} [since] timestamp in ms of the earliest trade to fetch
 * @param {int} [limit] the maximum number of trades to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
 */
func (this *Opinion) FetchMyTradesAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMyTradesBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) fetchMyTradesBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var outcome *string = ccxt.GetArgStringPtr(optionalArgs, 0, nil)
	_ = outcome
	var since *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	if ccxt.IsEqual(this.WalletAddress, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " fetchMyTrades() requires a walletAddress"))
	}

	ccxt.PanicOnError((<-this.LoadApiKeyAsync()))
	var outcomeObj any = nil
	var request map[string]any = map[string]any{
		"walletAddress": this.WalletAddress,
	}
	if outcome != nil {

		outcomeObj = (<-this.LoadOutcomeAsync(outcome))
		ccxt.PanicOnError(outcomeObj)
		var info map[string]any = ccxt.SafeMapTyped(outcomeObj, "info")
		request["marketId"] = this.SafeInteger(info, "marketId")
	}

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPrivateGetTradeUserWalletAddress(this.Extend(request, params))).Raw))
	var result map[string]any = ccxt.SafeMapTyped(response, "result")
	var trades []any = ccxt.SafeListTypedDefault(result, "list", []any{})
	var tradesLength int = len(trades)
	for i := 0; i < tradesLength; i++ {
		var trade any = func() any {
			if i >= 0 && i < len(trades) {
				return ccxt.DerefScalar(trades[i])
			}
			return nil
		}()
		var tokenId *string = this.SafeString(trade, "tokenId")
		var marketId *int64 = this.SafeInteger(trade, "marketId")
		if (tokenId == nil) && (marketId != nil) {

			var tradeMarket map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.LoadTradeMarketAsync(marketId))))
			var info map[string]any = ccxt.SafeMapTyped(tradeMarket, "info")
			var isYes bool = (this.SafeStringLower(trade, "outcomeSideEnum") != nil && *this.SafeStringLower(trade, "outcomeSideEnum") == "yes")
			ccxt.AddElementToObject(trade, "tokenId", func() any {
				if isYes {
					return this.SafeString(info, "yesTokenId")
				}
				return this.SafeString(info, "noTokenId")
			}())
		}
	}

	ch <- this.ParsePredictionTrades(trades, outcomeObj, since, limit)
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#loadTradeMarket
 * @description fetches and caches a single market by its numeric marketId, and indexes its outcomes
 * @param {int} marketId the numeric market id
 * @returns {object} the parsed market
 */
func (this *Opinion) LoadTradeMarketAsync(marketId any) <-chan any {
	ch := make(chan any, 1)
	go this.loadTradeMarketBody(ch, marketId)
	return ch
}
func (this *Opinion) loadTradeMarketBody(ch chan any, marketId any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	if ccxt.IsEqual(marketId, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " loadTradeMarket() requires a marketId"))
	}
	var cacheKey string = "tradeMarketsById"
	var cached any = this.SafeDict(this.Options, cacheKey, map[string]any{})
	var idStr string = ccxt.ToString(marketId)
	var existing any = this.SafeDict(cached, idStr)
	if !ccxt.IsEqual(existing, nil) {

		ch <- existing
		return nil
	}

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPublicGetMarketMarketId(map[string]any{
		"marketId": marketId,
	})).Raw))
	var result map[string]any = ccxt.SafeMapTyped(response, "result")
	var data map[string]any = ccxt.MapTyped(this.SafeDict(result, "data", map[string]any{}))
	var market any = this.ParseOpinionMarket(data)
	if ccxt.IsEqual(market, nil) {
		panic(ccxt.ExchangeError(this.Id + " loadTradeMarket() could not parse market " + idStr))
	}
	if this.Markets == nil {
		this.Markets = this.CreateSafeDictionary()
	}
	var marketHandle *string = this.SafeString(market, "market", "")
	ccxt.AddElementToObject(this.Markets, marketHandle, market)
	this.IndexMarketOutcomes(market)
	ccxt.AddElementToObject(cached, idStr, market)
	this.Options.Store(cacheKey, cached)

	ch <- market
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#parsePredictionTrade
 * @description parses a raw opinion trade object into a unified trade object
 * @param {object} trade the raw opinion TradeData object
 * @param {object} [market] the outcome object the trade belongs to
 * @returns {object} a [prediction trade structure](https://docs.ccxt.com/#/?id=prediction-trade-structure)
 */
func (this *Opinion) ParsePredictionTrade(trade any, optionalArgs ...any) any {
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var tokenId *string = this.SafeString(trade, "tokenId")
	var outcomeObj map[string]any = this.SafeOutcome(tokenId, market)
	var timestamp *int64 = this.SafeTimestamp(trade, "createdAt")
	var side *string = this.SafeStringLower(trade, "side")
	return this.SafePredictionTrade(map[string]any{
		"id":        this.SafeString(trade, "txHash"),
		"timestamp": timestamp,
		"side":      side,
		"price":     this.SafeNumber(trade, "price"),
		"amount":    this.SafeNumber(trade, "shares"),
		"cost":      this.SafeNumber(trade, "amount"),
		"fee": map[string]any{
			"cost":     this.SafeNumber(trade, "fee"),
			"currency": "USDT",
		},
		"outcome":   this.SafeString(outcomeObj, "outcome"),
		"outcomeId": this.SafeString2(outcomeObj, "outcomeId", "id"),
		"label":     this.SafeString(outcomeObj, "label"),
		"market":    this.SafeString2(outcomeObj, "market", "outcome"),
	})
}

/**
 * @method
 * @name opinion#fetchBalance
 * @description fetches the authenticated user's quote-token balances
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/quote-token
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
 */
func (this *Opinion) FetchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	ccxt.PanicOnError((<-this.LoadApiKeyAsync()))
	var request map[string]any = map[string]any{
		"chain_id": "56",
	}

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPrivateGetUserBalance(this.Extend(request, params))).Raw))
	var result map[string]any = ccxt.SafeMapTyped(response, "result")
	var rawBalances []any = ccxt.SafeListTyped(result, "balances")
	var rawBalancesLength int = len(rawBalances)
	for i := 0; i < rawBalancesLength; i++ {
		var rawBalance any = func() any {
			if i >= 0 && i < len(rawBalances) {
				return ccxt.DerefScalar(rawBalances[i])
			}
			return nil
		}()
		var quoteTokenAddress *string = this.SafeString(rawBalance, "quoteToken")

		var quoteToken map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.LoadQuoteTokenAsync(quoteTokenAddress))))
		ccxt.AddElementToObject(rawBalance, "symbol", this.SafeString(quoteToken, "symbol", "USDT"))
	}

	ch <- this.ParseBalance(response)
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#parseBalance
 * @description parses an opinion user-balance response into a unified balances object
 * @param {object} response the raw user-balance response
 * @returns {object} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
 */
func (this *Opinion) ParseBalance(response any) any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	var data map[string]any = ccxt.SafeMapTyped(response, "result")
	var balances []any = ccxt.SafeListTyped(data, "balances")
	var balancesLength int = len(balances)
	for i := 0; i < balancesLength; i++ {
		var balance map[string]any = ccxt.SafeMapTyped(balances, i)
		var code *string = this.SafeString(balance, "symbol", "USDT")
		ccxt.AddElementToObject(result, code, map[string]any{
			"free":  this.SafeNumber(balance, "availableBalance"),
			"used":  this.SafeNumber(balance, "frozenBalance"),
			"total": this.SafeNumber(balance, "totalBalance"),
		})
	}
	return this.SafeBalance(result)
}

/**
 * @method
 * @name opinion#fetchPositions
 * @description fetches the authenticated user's open positions
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/position
 * @param {string[]} [outcomes] filter by unified outcomes or outcome token ids
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} a list of [prediction position structures](https://docs.ccxt.com/#/?id=prediction-position-structure)
 */
func (this *Opinion) FetchPositionsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchPositionsBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) fetchPositionsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	outcomes := ccxt.GetArg(optionalArgs, 0, nil)
	_ = outcomes
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if ccxt.IsEqual(this.WalletAddress, nil) {
		panic(ccxt.ArgumentsRequired(this.Id + " fetchPositions() requires a walletAddress"))
	}

	ccxt.PanicOnError((<-this.LoadApiKeyAsync()))
	var outcomesLength int = 0
	if outcomes != nil {
		outcomesLength = ccxt.GetArrayLength(outcomes)

		ccxt.PanicOnError((<-this.LoadOutcomesAsync(outcomes)))
	}
	var request map[string]any = map[string]any{
		"walletAddress": this.WalletAddress,
	}

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPrivateGetPositionsUserWalletAddress(this.Extend(request, params))).Raw))
	var result map[string]any = ccxt.SafeMapTyped(response, "result")
	var positions []any = ccxt.SafeListTypedDefault(result, "list", []any{})
	var parsed any = this.ParsePredictionPositions(positions)
	if outcomesLength == 0 {

		ch <- parsed
		return nil
	}
	var wantedTokenIds map[string]any = map[string]any{}
	// copy to a plain list so the strict null checks see one shape
	var outcomesList any = func() any {
		if outcomes == nil {
			return []any{}
		}
		return outcomes
	}()
	for i := 0; i < ccxt.GetArrayLength(outcomesList); i++ {
		var outcomeObj map[string]any = this.Outcome(ccxt.GetValue(outcomesList, i))
		var tokenId *string = this.SafeString(outcomeObj, "outcomeId")
		if tokenId != nil {
			wantedTokenIds[*tokenId] = true
		}
	}
	var filtered []any = []any{}
	for i := 0; i < ccxt.GetArrayLength(parsed); i++ {
		var position any = ccxt.GetValue(parsed, i)
		var info map[string]any = ccxt.SafeMapTyped(position, "info")
		var tokenId *string = this.SafeString(info, "tokenId")
		if (tokenId != nil) && (func() bool {
			if tokenId == nil {
				return false
			}
			_, ok := wantedTokenIds[*tokenId]
			return ok
		}()) {
			filtered = append(filtered, position)
		}
	}

	ch <- filtered
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#parsePredictionPosition
 * @description parses a raw opinion position object into a unified position object
 * @param {object} position the raw opinion PositionData object
 * @param {object} [market] the outcome object the position belongs to
 * @returns {object} a [prediction position structure](https://docs.ccxt.com/#/?id=prediction-position-structure)
 */
func (this *Opinion) ParsePredictionPosition(position any, optionalArgs ...any) any {
	market := ccxt.GetArg(optionalArgs, 0, nil)
	_ = market
	var tokenId *string = this.SafeString(position, "tokenId")
	var outcomeObj map[string]any = this.SafeOutcome(tokenId, market)
	var outcomeSideEnum *string = this.SafeStringLower(position, "outcomeSideEnum")
	return this.SafePredictionPosition(map[string]any{
		"contracts":     this.SafeNumber(position, "sharesOwned"),
		"side":          outcomeSideEnum,
		"unrealizedPnl": this.SafeNumber(position, "unrealizedPnl"),
		"entryPrice":    this.SafeNumber(position, "avgEntryPrice"),
		"outcome":       this.SafeString(outcomeObj, "outcome"),
		"outcomeId":     this.SafeString2(outcomeObj, "outcomeId", "id"),
		"label":         this.SafeString(outcomeObj, "label"),
		"market":        this.SafeString2(outcomeObj, "market", "outcome"),
		"info":          position,
	})
}
func (this *Opinion) HashMessage(message any) any {
	return ccxt.Add("0x", this.Hash(message, ccxt.Keccak, "hex"))
}
func (this *Opinion) SignHash(hash any, privateKey string) any {
	var signature map[string]any = ccxt.Ecdsa(ccxt.Slice(hash, ccxt.OpNeg(64), nil), privateKey[max(len(privateKey)-64, 0):], ccxt.Secp256k1, nil)
	// assign before padStart so the PHP str_pad regex matches
	var rRaw *string = ccxt.SafeStringPtr(signature["r"])
	var sRaw *string = ccxt.SafeStringPtr(signature["s"])
	var r string = ccxt.PadStart(rRaw, 64, "0")
	var s string = ccxt.PadStart(sRaw, 64, "0")
	return map[string]any{
		"r": "0x" + r,
		"s": "0x" + s,
		"v": this.Sum(27, signature["v"]),
	}
}
func (this *Opinion) SignMessage(message any, privateKey any) any {
	return this.SignHash(this.HashMessage(message), ccxt.Slice(privateKey, ccxt.OpNeg(64), nil))
}
func (this *Opinion) SignApiKeyAuth(walletAddress any, action any, timestamp any) any {
	// EIP-712 signature used to create/get/delete an API key (wallet-authenticated key management)
	var domain map[string]any = map[string]any{
		"name":    "Opinion OpenAPI",
		"version": "1",
		"chainId": 56,
	}
	var messageTypes map[string]any = map[string]any{
		"OpinionApiKeyAuth": []any{map[string]any{
			"name": "walletAddress",
			"type": "address",
		}, map[string]any{
			"name": "action",
			"type": "string",
		}, map[string]any{
			"name": "timestamp",
			"type": "string",
		}},
	}
	var messageData map[string]any = map[string]any{
		"walletAddress": walletAddress,
		"action":        action,
		"timestamp":     timestamp,
	}
	var encoded any = this.EthEncodeStructuredData(domain, messageTypes, messageData)
	var sig any = this.SignMessage(encoded, this.PrivateKey)
	return "0x" + this.Remove0xPrefix(ccxt.GetValue(sig, "r")) + this.Remove0xPrefix(ccxt.GetValue(sig, "s")) + this.IntToBase16(ccxt.GetValue(sig, "v"))
}

/**
 * @method
 * @name opinion#createApiKey
 * @description self-service creation of an Open API key linked to this.walletAddress via
 * an EIP-712-signed request - there is no "generate key" button in the Opinion GUI, this is
 * the only documented way to obtain a wallet-linked key
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
 * @param {object} [params] extra parameters
 * @returns {object} the api credentials { apiKey, walletAddress }
 */
func (this *Opinion) CreateApiKeyAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.createApiKeyBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) createApiKeyBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPrivatePostAuthApiKey(params)).Raw))
	var result map[string]any = ccxt.MapTyped(this.SafeDict(response, "result", map[string]any{}))

	ch <- this.SetApiCredentials(result)
	return nil
}

/**
 * @method
 * @name opinion#fetchApiKey
 * @description fetches the currently active Open API key for this.walletAddress
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
 * @param {object} [params] extra parameters
 * @returns {object} the api credentials { apiKey, walletAddress }
 */
func (this *Opinion) FetchApiKeyAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchApiKeyBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) fetchApiKeyBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = ccxt.MapTyped(ccxt.PanicOnError((<-this.OpinionPrivateGetAuthApiKey(params)).Raw))
	var result map[string]any = ccxt.MapTyped(this.SafeDict(response, "result", map[string]any{}))

	ch <- this.SetApiCredentials(result)
	return nil
}

/**
 * @method
 * @name opinion#deleteApiKey
 * @description revokes the Open API key for this.walletAddress
 * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
 * @param {object} [params] extra parameters
 * @returns {object} raw response, result.deleted confirms revocation
 */
func (this *Opinion) DeleteApiKeyAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.deleteApiKeyBody(ch, optionalArgs...)
	return ch
}
func (this *Opinion) deleteApiKeyBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.OpinionPrivateDeleteAuthApiKey(params)).Raw
	ccxt.PanicOnError(response)
	this.Options.Store("apiKey", nil)
	// sign() prefers this.apiKey over options['apiKey'] - clear it too, or a directly-set
	// exchange.apiKey would keep being used for private calls after the key is revoked.
	// an empty string, not undefined: the strict base types the credential as string, and
	// sign() treats an empty key as absent
	this.ApiKey = ""

	ch <- response
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#loadApiKey
 * @description ensures an apiKey is available before a private call - reuses a directly-set key, otherwise
 * self-issues one from the walletAddress/privateKey via fetchApiKey(), falling back to createApiKey() when
 * the wallet has no key yet; freshly created keys can take ~15 seconds to activate venue-side
 * @returns {string} the apiKey
 */
func (this *Opinion) LoadApiKeyAsync() <-chan any {
	ch := make(chan any, 1)
	go this.loadApiKeyBody(ch)
	return ch
}
func (this *Opinion) loadApiKeyBody(ch chan any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var hasDirectApiKey bool = !ccxt.EvalTruthy(this.IsEmptyString(this.ApiKey))
	if hasDirectApiKey {

		ch <- this.ApiKey
		return nil
	}
	var optionsKey *string = this.SafeString(this.Options, "apiKey")
	if optionsKey != nil {

		ch <- optionsKey
		return nil
	}
	if (ccxt.IsEqual(this.WalletAddress, nil)) || (ccxt.IsEqual(this.PrivateKey, nil)) {
		panic(ccxt.AuthenticationError(this.Id + " private endpoints require an apiKey, or a walletAddress and privateKey to self-issue one"))
	}
	var creds any = nil

	{
		func(this *Opinion) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Opinion) any {
						// catch block:
						// no key exists for this wallet yet (11010) - self-issue one; any other
						// failure (unregistered wallet, disabled issuance) surfaces from the create call

						creds = (<-this.CreateApiKeyAsync())
						ccxt.PanicOnError(creds)
						return nil
					}(this)
				}
			}()
			// try block:

			creds = (<-this.FetchApiKeyAsync())
			ccxt.PanicOnError(creds)
			return nil
		}(this)

	}

	ch <- this.SafeString(creds, "apiKey")
	return nil
}
func (this *Opinion) SetApiCredentials(response any) any {
	//
	//     { "apiKey": "...", "walletAddress": "..." }
	//
	var creds map[string]any = map[string]any{
		"apiKey":        this.SafeString(response, "apiKey"),
		"walletAddress": this.SafeString(response, "walletAddress"),
	}
	this.Options.Store("apiKey", creds["apiKey"])
	// checkRequiredCredentials() (called by createOrder()) checks this.apiKey, not
	// options['apiKey'] - keep both in sync, same as deleteApiKey() clearing both
	this.ApiKey = creds["apiKey"]
	return creds
}

/**
 * @ignore
 * @method
 * @name opinion#opinionWsUrl
 * @description builds the websocket url - the venue authenticates the whole connection with the apiKey passed as a query parameter, for public and private channels alike
 * @returns {string} the websocket url
 */
func (this *Opinion) OpinionWsUrl() any {
	var hasDirectApiKey bool = !ccxt.EvalTruthy(this.IsEmptyString(this.ApiKey))
	var apiKey any = func() any {
		if hasDirectApiKey {
			return this.ApiKey
		}
		return this.SafeString(this.Options, "apiKey")
	}()
	if apiKey == nil {
		panic(ccxt.AuthenticationError(this.Id + " websocket requires an apiKey - set it directly or call createApiKey()/fetchApiKey() first"))
	}
	var wsUrl *string = this.SafeString(ccxt.GetValue(this.Urls, "api"), "ws", "")
	return ccxt.Add(*wsUrl+"?apikey=", apiKey)
}
func (this *Opinion) Ping(client any) any {
	// the venue keeps the socket open only while application-level heartbeats arrive
	return map[string]any{
		"action": "HEARTBEAT",
	}
}

/**
 * @ignore
 * @method
 * @name opinion#subscribeOpinionChannel
 * @description subscribes to one venue channel scoped by the binary marketId and waits on the given message hash
 * @param {string} messageHash the internal hash the awaited payload resolves on
 * @param {string} channel the venue channel name (e.g. 'market.depth.diff')
 * @param {int} marketId the numeric binary market id
 * @returns {any} the first resolved payload
 */
func (this *Opinion) SubscribeOpinionChannelAsync(messageHash any, channel string, marketId any) <-chan any {
	ch := make(chan any, 1)
	go this.subscribeOpinionChannelBody(ch, messageHash, channel, marketId)
	return ch
}
func (this *Opinion) subscribeOpinionChannelBody(ch chan any, messageHash any, channel string, marketId any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)

	ccxt.PanicOnError((<-this.LoadApiKeyAsync()))
	var url any = this.OpinionWsUrl()
	var subscriptionKey *string = ccxt.SafeStringPtr(ccxt.Add(channel+":", this.NumberToString(marketId)))
	var subscribeMsg map[string]any = map[string]any{
		"action":   "SUBSCRIBE",
		"channel":  channel,
		"marketId": marketId,
	}

	ch <- ccxt.PanicOnError((<-this.Watch(url, messageHash, subscribeMsg, subscriptionKey)))
	return nil
}
func (this *Opinion) HandleMessage(client any, message any) {
	// every data payload carries its channel name in msgType; frames without one -
	// subscribe acks and heartbeat echoes - carry nothing to route
	var msgType *string = this.SafeString(message, "msgType")
	if msgType == nil {
		return
	}
	if msgType != nil && *msgType == "market.depth.diff" {
		this.HandleOrderBook(client, message)
	} else if msgType != nil && *msgType == "market.last.price" {
		this.HandleTicker(client, message)
	} else if msgType != nil && *msgType == "market.last.trade" {
		this.HandleTrades(client, message)
	} else if msgType != nil && *msgType == "trade.order.update" {
		this.HandleOrder(client, message)
	} else if msgType != nil && *msgType == "trade.record.new" {
		this.HandleMyTrade(client, message)
	}
}

/**
 * @ignore
 * @method
 * @name opinion#opinionOutcomeByMarketIdSide
 * @description resolves a cached outcome object from the numeric marketId + outcomeSide (1 yes / 2 no) the user channels report instead of a tokenId - cache-only, returns undefined on a cold cache
 * @param {int} marketId the numeric binary market id
 * @param {int} outcomeSide 1 for the yes token, 2 for the no token
 * @returns {object} the outcome object, or undefined
 */
func (this *Opinion) OpinionOutcomeByMarketIdSide(marketId any, outcomeSide any) any {
	if (ccxt.IsEqual(marketId, nil)) || (this.Markets == nil) {
		return nil
	}
	var marketKeys []string = ccxt.ObjectKeys(this.Markets)
	var marketKeysLength int = len(marketKeys)
	for i := 0; i < marketKeysLength; i++ {
		var market map[string]any = ccxt.SafeMapTyped(this.Markets, ccxt.GetValue(marketKeys, i))
		var info map[string]any = ccxt.SafeMapTyped(market, "info")
		if ccxt.IsEqual(this.SafeInteger(info, "marketId"), marketId) {
			var outcomes any = this.SafeList(market, "outcomes", []any{})
			var index int = func() int {
				if ccxt.IsEqual(outcomeSide, 2) {
					return 1
				}
				return 0
			}()
			return this.SafeDict(outcomes, index)
		}
	}
	return nil
}

/**
 * @method
 * @name opinion#watchOrderBook
 * @description streams the order book of an outcome token; the channel is delta-only so the live book is seeded from the REST snapshot
 * @see https://docs.opinion.trade/developer-guide/opinion-websocket/market-channels
 * @param {string} outcome unified outcome or outcome token id
 * @param {int} [limit] the maximum number of order book entries to return
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
 */
func (this *Opinion) WatchOrderBookAsync(outcome any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.watchOrderBookBody(ch, outcome, optionalArgs...)
	return ch
}
func (this *Opinion) watchOrderBookBody(ch chan any, outcome any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit
	var params map[string]any = ccxt.GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	outcomeObj := (<-this.LoadOutcomeAsync(outcome))
	ccxt.PanicOnError(outcomeObj)
	var info map[string]any = ccxt.SafeMapTyped(outcomeObj, "info")
	var marketId *int64 = this.SafeInteger(info, "marketId")
	var sym any = this.SafeOutcomeSymbol(outcome, outcomeObj)
	var channel string = "market.depth.diff"
	var messageHash *string = ccxt.SafeStringPtr(ccxt.Add("orderbook::", sym))

	ccxt.PanicOnError((<-this.LoadApiKeyAsync()))
	var url any = this.OpinionWsUrl()
	var client any = this.Client(url)
	var subscriptionKey *string = ccxt.SafeStringPtr(ccxt.Add(channel+":", this.NumberToString(marketId)))
	var isNewSubscription bool = ccxt.IsEqual(this.SafeValue(client.(ccxt.ClientInterface).GetSubscriptions(), subscriptionKey), nil)
	if isNewSubscription {

		ccxt.PanicOnError((<-this.SeedOrderBookAsync(outcome, sym, limit)))
	}
	var subscribeMsg map[string]any = map[string]any{
		"action":   "SUBSCRIBE",
		"channel":  channel,
		"marketId": marketId,
	}
	var future any = this.Watch(url, messageHash, subscribeMsg, subscriptionKey)
	if isNewSubscription {
		// return the freshly-seeded book immediately instead of blocking until the next delta
		client.(ccxt.ClientInterface).Resolve(this.SafeValue(this.Orderbooks, sym), messageHash)
	}

	orderbook := <-future.(<-chan any)
	ccxt.PanicOnError(orderbook)

	ch <- orderbook.(ccxt.OrderBookInterface).Limit()
	return nil
}
func (this *Opinion) SeedOrderBookAsync(outcome any, sym any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.seedOrderBookBody(ch, outcome, sym, optionalArgs...)
	return ch
}
func (this *Opinion) seedOrderBookBody(ch chan any, outcome any, sym any, optionalArgs ...any) any {
	defer close(ch)
	defer ccxt.ReturnPanicError(ch)
	// the depth channel streams single-level deltas only, so seed the live book from the REST snapshot
	var limit *int64 = ccxt.GetArgInt64Ptr(optionalArgs, 0, nil)
	_ = limit

	snapshot := (<-this.FetchOrderBookAsync(outcome, limit))
	ccxt.PanicOnError(snapshot)
	var orderbook any = this.OrderBook(map[string]any{})
	orderbook.(ccxt.OrderBookInterface).Reset(snapshot)
	ccxt.AddElementToObject(this.Orderbooks, sym, orderbook)
	return nil
}
func (this *Opinion) HandleOrderBook(client any, message any) {
	//
	//     {
	//         "marketId": 2764,
	//         "tokenId": "19120407572139442221452465677574895365338028945317996490376653704877573103648",
	//         "outcomeSide": 1,
	//         "side": "bids",
	//         "price": "0.2",
	//         "size": "50",
	//         "msgType": "market.depth.diff"
	//     }
	//
	var tokenId *string = this.SafeString(message, "tokenId")
	var outcomeObj map[string]any = ccxt.SafeMapTyped(this.Outcomes_by_id, tokenId)
	var sym *string = this.SafeString(outcomeObj, "outcome")
	if sym == nil {
		return
	}
	if ccxt.IsEqual(this.SafeValue(this.Orderbooks, sym), nil) {
		// the delta belongs to the market's other token, whose book is not being watched
		return
	}
	var orderbook any = ccxt.GetValue(this.Orderbooks, sym)
	var sideStr *string = this.SafeString(message, "side")
	var bookSide any = func() any {
		if sideStr != nil && *sideStr == "bids" {
			return ccxt.GetValue(orderbook, "bids")
		}
		return ccxt.GetValue(orderbook, "asks")
	}()
	var price *float64 = this.SafeNumber(message, "price")
	var size *float64 = this.SafeNumber(message, "size")
	bookSide.(ccxt.IOrderBookSide).StoreArray([]any{price, size})
	ccxt.AddElementToObject(orderbook, "timestamp", nil)
	ccxt.AddElementToObject(orderbook, "datetime", nil)
	client.(ccxt.ClientInterface).Resolve(orderbook, "orderbook::"+*sym)
}

