/**
 * @ignore
 * @method
 * @name opinion#parseWsOrderStatus
 * @description maps the numeric order status of the websocket order channel onto the unified vocabulary
 * @param {int} status the numeric order status
 * @returns {string} a unified order status, or undefined
 */
func (this *Opinion) ParseWsOrderStatus(status any) any {
	// per the venue docs: 1 pending, 2 finished, 3 canceled, 4 expired, 5 failed
	if ccxt.IsEqual(status, 1) {
		return "open"
	}
	if ccxt.IsEqual(status, 2) {
		return "closed"
	}
	if ccxt.IsEqual(status, 3) {
		return "canceled"
	}
	if ccxt.IsEqual(status, 4) {
		return "expired"
	}
	if ccxt.IsEqual(status, 5) {
		return "rejected"
	}
	return nil
}
func (this *Opinion) HandleOrder(client any, message any) {
	//
	//     {
	//         "orderUpdateType": "orderConfirm",
	//         "marketId": 2770,
	//         "rootMarketId": 122,
	//         "orderId": "a11ee07e-e22f-11f0-9714-0a58a9feac02",
	//         "side": 1,
	//         "outcomeSide": 1,
	//         "price": "0.150000000000000000",
	//         "shares": "66.66",
	//         "amount": "9.999000000000000000",
	//         "status": 1,
	//         "tradingMethod": 2,
	//         "quoteToken": "0x55d398326f99059fF775485246999027B3197955",
	//         "createdAt": 1766735464,
	//         "expiresAt": 0,
	//         "chainId": "56",
	//         "filledShares": "10.000000000000000000",
	//         "filledAmount": "1.500000000000000000",
	//         "msgType": "trade.order.update"
	//     }
	//
	var marketId *int64 = this.SafeInteger(message, "marketId")
	var outcomeSide *int64 = this.SafeInteger(message, "outcomeSide")
	var outcomeObj any = this.OpinionOutcomeByMarketIdSide(marketId, outcomeSide)
	var timestamp *int64 = this.SafeTimestamp(message, "createdAt")
	// unlike the REST order body (0 buy / 1 sell), the websocket channel uses 1 buy / 2 sell
	// per the docs and confirmed live
	var sideInt *int64 = this.SafeInteger(message, "side")
	var side string = "sell"
	if sideInt != nil && *sideInt == 1 {
		side = "buy"
	}
	var tradingMethod *int64 = this.SafeInteger(message, "tradingMethod")
	var typeVar string = "limit"
	if tradingMethod != nil && *tradingMethod == 1 {
		typeVar = "market"
	}
	var order any = this.SafePredictionOrder(map[string]any{
		"id":                 this.SafeString(message, "orderId"),
		"clientOrderId":      nil,
		"info":               message,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             this.ParseWsOrderStatus(this.SafeInteger(message, "status")),
		"outcome":            this.SafeString(outcomeObj, "outcome"),
		"outcomeId":          this.SafeString(outcomeObj, "outcomeId"),
		"label":              this.SafeString(outcomeObj, "label"),
		"market":             this.SafeString(outcomeObj, "market"),
		"type":               typeVar,
		"side":               side,
		"price":              this.SafeNumber(message, "price"),
		"amount":             this.SafeNumber(message, "shares"),
		"cost":               this.SafeNumber(message, "filledAmount"),
		"filled":             this.SafeNumber(message, "filledShares"),
		"fee":                nil,
		"trades":             []any{},
	}, outcomeObj)
	if ccxt.IsEqual(this.Orders, nil) {
		var limit *int64 = this.SafeInteger(this.Options, "ordersLimit", 1000)
		this.Orders = ccxt.NewArrayCacheByOutcomeById(limit)
	}
	var stored any = this.Orders
	stored.(ccxt.Appender).Append(order)
	client.(ccxt.ClientInterface).Resolve(stored, "orders")
}

