func (this *Opinion) HandleErrors(code any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if ccxt.IsEqual(response, nil) {
		return nil
	}
	var errno *int64 = this.SafeInteger(response, "errno")
	if (errno != nil) && (errno == nil || *errno != 0) {
		var errmsg *string = this.SafeString(response, "errmsg", "")
		var feedback *string = ccxt.SafeStringPtr(ccxt.Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], this.NumberToString(errno), feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errmsg, feedback)
		panic(ccxt.ExchangeError(feedback))
	}
	return nil
}

/**
 * @ignore
 * @method
 * @name opinion#sign
 * @description builds the request url and attaches the apikey/EIP-712 authentication headers for private endpoints
 * @param {string} path the endpoint path
 * @param {string|string[]} api the api group and access level
 * @param {string} method the http method
 * @param {object} params the request parameters
 * @param {object} [headers] request headers
 * @param {string} [body] the request body
 * @returns {object} a dict with url, method, body and headers
 */
func (this *Opinion) Sign(path any, optionalArgs ...any) any {
	api := ccxt.GetArg(optionalArgs, 0, "opinion")
	_ = api
	var method string = ccxt.GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := ccxt.GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := ccxt.GetArg(optionalArgs, 3, nil)
	_ = headers
	body := ccxt.GetArg(optionalArgs, 4, nil)
	_ = body
	var apiGroup any = func() any {
		if ccxt.IsString(api) {
			return api
		}
		return ccxt.GetValue(api, 0)
	}()
	var access any = func() any {
		if ccxt.IsString(api) {
			return "public"
		}
		return ccxt.GetValue(api, 1)
	}()
	var baseUrls any = ccxt.GetValue(this.Urls, "api")
	var baseUrl *string = this.SafeString(baseUrls, apiGroup, ccxt.GetValue(baseUrls, "opinion"))
	var url any = ccxt.Add(*baseUrl+"/", this.ImplodeParams(path, params))
	var query any = this.Omit(params, this.ExtractParams(path))
	var existingHeaders any = func() any {
		if !ccxt.IsEqual(headers, nil) {
			return headers
		}
		return map[string]any{}
	}()
	headers = this.Extend(map[string]any{
		"Accept":       "application/json",
		"Content-Type": "application/json",
	}, existingHeaders)
	if ccxt.IsEqual(access, "private") {
		if ccxt.IsEqual(path, "auth/api-key") {
			// wallet-signature scheme: no apiKey involved, the signature itself is the credential
			if (ccxt.IsEqual(this.WalletAddress, nil)) || (ccxt.IsEqual(this.PrivateKey, nil)) {
				panic(ccxt.ArgumentsRequired(ccxt.Add(ccxt.Add(this.Id+" ", path), " requires a walletAddress and privateKey")))
			}
			var actionByMethod map[string]any = map[string]any{
				"POST":   "create",
				"GET":    "get",
				"DELETE": "delete",
			}
			var action *string = this.SafeString(actionByMethod, method, "get")
			var timestamp *string = this.NumberToString(this.Seconds())
			ccxt.AddElementToObject(headers, "OPINION_ADDRESS", this.WalletAddress)
			ccxt.AddElementToObject(headers, "OPINION_SIGNATURE", this.SignApiKeyAuth(this.WalletAddress, action, timestamp))
			ccxt.AddElementToObject(headers, "OPINION_TIMESTAMP", timestamp)
		} else {
			// an empty this.apiKey counts as absent - deleteApiKey clears it to '' (the
			// strict base types the credential as string, undefined can not be assigned)
			var hasDirectApiKey bool = !ccxt.EvalTruthy(this.IsEmptyString(this.ApiKey))
			var apiKey any = func() any {
				if hasDirectApiKey {
					return this.ApiKey
				}
				return this.SafeString(this.Options, "apiKey")
			}()
			if apiKey == nil {
				panic(ccxt.AuthenticationError(ccxt.Add(ccxt.Add(this.Id+" ", path), " requires an apiKey - set it directly or call createApiKey()/fetchApiKey() first")))
			}
			ccxt.AddElementToObject(headers, "apikey", apiKey)
		}
	}
	if method == "GET" {
		if len(ccxt.ObjectKeys(query)) > 0 {
			url = ccxt.Add(url, "?"+this.Urlencode(query))
		}
	} else {
		body = this.Json(query)
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}

func NewOpinion(userConfig map[string]any) *Opinion {
	p := newOpinion()
	p.Init(userConfig)
	return p
}

func (this *Opinion) Init(userConfig map[string]any) {
	this.BaseExchange = ccxt.BaseExchange{}
	this.BaseExchange.DerivedExchange = this
	this.BaseExchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = ccxt.NewBaseExchangeTyped(&this.BaseExchange)
}

